51	 * @author Vitaliy Fedoriv
52	 */
53	
54	@RestController
55	@CrossOrigin(exposedHeaders = "errors, content-type")
56	@RequestMapping("/api")
57	public class OwnerRestControllerV1 implements OwnersApi {
58	
59	    private final ClinicService clinicService;
60	
61	    private final OwnerMapper ownerMapper;
62	
63	    private final PetMapper petMapper;
64	
65	    private final VisitMapper visitMapper;
66	
67	    public OwnerRestControllerV1(ClinicService clinicService,
68	                                 OwnerMapper ownerMapper,
69	                                 PetMapper petMapper,
70	                                 VisitMapper visitMapper) {
71	        this.clinicService = clinicService;
72	        this.ownerMapper = ownerMapper;
73	        this.petMapper = petMapper;
74	        this.visitMapper = visitMapper;
75	    }
76	
77	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
78	    @Override
79	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
80	        Collection<Owner> owners;
81	        if (lastName != null) {
82	            owners = this.clinicService.findOwnerByLastName(lastName);
83	        } else {
84	            owners = this.clinicService.findAllOwners();
85	        }
86	        if (owners.isEmpty()) {
87	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
88	        }
89	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
90	    }
91	
92	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
93	    @Override
94	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
95	        Owner owner = this.clinicService.findOwnerById(ownerId);
96	        if (owner == null) {
97	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
98	        }
99	        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK);
100	    }
101	
102	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
103	    @Override
104	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
105	        HttpHeaders headers = new HttpHeaders();
106	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
107	        owner.setTelephone(normalizeTelephone(owner.getTelephone()));
108	        owner.setCity(canonicalCity(owner.getCity()));
109	        if (owner.getRegistrationDate() == null) {
110	            owner.setRegistrationDate(LocalDate.now());
111	        }
112	        if (isDailyRegistrationLimitReached()) {
113	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
114	        }
115	        if (isCityCapacityReached(owner.getCity())) {
116	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
117	        }
118	        if (isDuplicateOwner(owner) || isDuplicateEmail(owner)) {
119	            return new ResponseEntity<>(HttpStatus.CONFLICT);
120	        }
121	        owner.setMembershipNumber(this.clinicService.findAllOwners().size() + 1);
122	        owner.setCustomerCode(customerCode(owner));
123	        this.clinicService.saveOwner(owner);
124	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
125	        headers.setLocation(UriComponentsBuilder.newInstance()
126	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
127	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
128	    }
129	
130	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
131	    @Override
132	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
133	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
134	        if (currentOwner == null) {
135	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
136	        }
137	        currentOwner.setAddress(ownerFieldsDto.getAddress());
138	        currentOwner.setCity(ownerFieldsDto.getCity());
139	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
140	        currentOwner.setLastName(ownerFieldsDto.getLastName());
141	        currentOwner.setTelephone(normalizeTelephone(ownerFieldsDto.getTelephone()));
142	        this.clinicService.saveOwner(currentOwner);
143	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
144	    }
145	
146	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
147	    @Transactional
148	    @Override
149	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
150	        Owner owner = this.clinicService.findOwnerById(ownerId);
151	        if (owner == null) {
152	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
153	        }
154	        this.clinicService.deleteOwner(owner);
155	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
156	    }
157	
158	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
159	    @Override
160	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
161	        Owner owner = this.clinicService.findOwnerById(ownerId);
162	        if (owner == null) {
163	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
164	        }
165	        HttpHeaders headers = new HttpHeaders();
166	        Pet pet = petMapper.toPet(petFieldsDto);
167	        owner.setId(ownerId);
168	        pet.setOwner(owner);
169	        pet.getType().setName(null);
170	        this.clinicService.savePet(pet);
171	        PetDto petDto = petMapper.toPetDto(pet);
172	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
173	            .buildAndExpand(pet.getId()).toUri());
174	        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
175	    }
